<script setup lang="ts">
import {computed} from 'vue';import {useRoute,useRouter} from 'vue-router';import PageHeading from '../components/PageHeading.vue';import QuotaCard from '../components/QuotaCard.vue';import {useData} from '../store';import {risk,accountName} from '../domain';
const data=useData(),route=useRoute(),router=useRouter();
const filter=computed({get:()=>String(route.query.status||(route.query.risk==='1'?'risk':'all')),set:value=>{void router.replace({query:{...route.query,status:value,risk:undefined}});}});
const query=computed({get:()=>String(route.query.q||''),set:value=>{void router.replace({query:{...route.query,q:value||undefined}});}});
const list=computed(()=>data.accounts.filter(a=>(filter.value==='all'||filter.value==='active'&&a.in_use||filter.value==='idle'&&!a.in_use||filter.value==='risk'&&risk(a))&&`${accountName(a)} ${a.owner||''}`.toLocaleLowerCase('zh-CN').includes(query.value.toLocaleLowerCase('zh-CN'))).sort((a,b)=>Number(b.in_use)-Number(a.in_use)||Number(risk(b))-Number(risk(a))||accountName(a).localeCompare(accountName(b),'zh-CN')));
const active=computed(()=>data.accounts.filter(a=>a.in_use).length),warnings=computed(()=>data.accounts.filter(risk).length);
</script><template><PageHeading title="账号额度" note="按账号独立保留最新完整额度；设备切号不移除历史账号，多个设备不叠加额度。" eyebrow="ACCOUNT CAPACITY"/><div class="quota-account-summary"><span>全部账号 <b>{{data.accounts.length}}</b></span><span>在用 <b>{{active}}</b></span><span>离线 / 待采集 <b>{{data.accounts.length-active}}</b></span><span>额度预警 <b>{{warnings}}</b></span></div><div class="toolbar"><el-radio-group v-model="filter"><el-radio-button value="all">全部</el-radio-button><el-radio-button value="active">在用</el-radio-button><el-radio-button value="idle">离线 / 待采集</el-radio-button><el-radio-button value="risk">额度预警</el-radio-button></el-radio-group><el-input v-model="query" clearable aria-label="搜索账号或负责人" placeholder="搜索账号或负责人" style="width:260px"/></div><div v-if="list.length" class="account-capacity-grid"><QuotaCard v-for="a in list" :key="a.key" :item="a"/></div><el-empty v-else description="没有符合条件的可见账号"/></template>
<style scoped>
.quota-account-summary{display:flex;gap:24px;flex-wrap:wrap;padding:16px 20px;margin-bottom:18px;background:var(--panel);border:1px solid var(--line);border-radius:10px;color:var(--muted)}.quota-account-summary b{font-size:calc(20px * var(--app-font-scale, 1.2));margin-left:8px;color:var(--text)}.account-capacity-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;align-items:stretch}@media(max-width:1200px){.account-capacity-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:760px){.account-capacity-grid{grid-template-columns:1fr}.quota-account-summary{gap:14px}}
</style>
